import { fileURLToPath } from 'node:url';
import { sql } from 'drizzle-orm';
import { migrate as runMigrations } from 'drizzle-orm/postgres-js/migrator';
import { createDb } from './db.ts';

/** SQL migrations generated by drizzle-kit (`pnpm --filter @wf/db generate`) plus the hand-written security ones. */
export const MIGRATIONS_FOLDER = fileURLToPath(new URL('../migrations', import.meta.url));

/**
 * Applies pending migrations in one transaction. Connect as `wf_migrate` so it owns every object it creates.
 * A session advisory lock makes concurrent starts (several web instances) apply them once.
 */
export async function migrate(migrateUrl: string): Promise<void> {
  const db = createDb(migrateUrl, { max: 1, statementTimeoutMs: 0 });
  try {
    await db.execute(sql`select pg_advisory_lock(hashtext('wf.migrate'))`);
    await runMigrations(db, { migrationsFolder: MIGRATIONS_FOLDER });
  } finally {
    // Ending the only session also releases the advisory lock.
    await db.$client.end();
  }
}
